# ============================================================
# AEGIS NIDS - Phase 6 Deploy Script (Low + Info + Bugfix)
# Generated from commit eb519db + Phase 6 fixes
# ============================================================
# What this script does:
#   1. Backs up each existing file (appends .phase6_backup)
#   2. Decodes base64 content and writes new file (UTF-8 BOM preserved)
#   3. Verifies line counts match expected values
#   4. Cleans up old backup files from prior phases
#   5. Runs `zig build` to confirm the project still compiles
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\best_practices_phase6_deploy.ps1
# ============================================================

$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }

Write-Host "[DEPLOY] AEGIS Phase 6 - Low + Info + Bugfix"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param(
        [string]$RelativePath,
        [string]$Base64Content,
        [int]$ExpectedLines
    )
    $FullPath = Join-Path $DeployRoot $RelativePath
    $BackupPath = "$FullPath.phase6_backup"

    # Backup existing file
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
        Write-Host "  [OK] Backup created"
    }

    # Decode base64 and write (preserves UTF-8 BOM)
    # $Base64Content is a single-quoted string literal - should be pure base64.
    try {
        $Bytes = [System.Convert]::FromBase64String($Base64Content)
    } catch {
        # DEBUG: If decode fails, dump diagnostics so we can see what's wrong.
        Write-Host "  [DEBUG] Base64 length: $($Base64Content.Length)"
        $preview_len = [Math]::Min(80, $Base64Content.Length)
        Write-Host "  [DEBUG] First $preview_len chars: $($Base64Content.Substring(0, $preview_len))"
        $tail_start = [Math]::Max(0, $Base64Content.Length - 80)
        $tail_len = $Base64Content.Length - $tail_start
        if ($tail_len -gt 0) {
            Write-Host "  [DEBUG] Last $tail_len chars: $($Base64Content.Substring($tail_start, $tail_len))"
        }
        # Show any non-base64 chars (A-Z, a-z, 0-9, +, /, = are valid)
        $invalid = $Base64Content -replace '[A-Za-z0-9+/=]', ''
        if ($invalid.Length -gt 0) {
            Write-Host "  [DEBUG] Invalid chars found (count=$($invalid.Length)):"
            $invalid_codes = $invalid.ToCharArray() | ForEach-Object { '{0:X4}' -f [int]$_ } | Select-Object -First 10
            Write-Host "  [DEBUG] Unicode code points: $($invalid_codes -join ' ')"
        } else {
            Write-Host "  [DEBUG] No invalid chars found (string is pure base64) - likely a length/padding issue"
        }
        throw
    }
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)

    # Verify line count (PowerShell Get-Content semantics)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] Line count mismatch: actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] Deployed: $ActualLines lines (expected $ExpectedLines)"
    }
}

# [1/7] core/nids_analyze.zig
$B64_1 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 1622 -Base64Content $B64_1

# [2/7] core/nids_capture.zig
$B64_2 = ''
Deploy-File -RelativePath "core/nids_capture.zig" -ExpectedLines 152 -Base64Content $B64_2

# [3/7] core/minifilter_reader.zig
$B64_3 = ''
Deploy-File -RelativePath "core/minifilter_reader.zig" -ExpectedLines 247 -Base64Content $B64_3

# [4/7] core/windows_capture.zig
$B64_4 = ''
Deploy-File -RelativePath "core/windows_capture.zig" -ExpectedLines 121 -Base64Content $B64_4

# [5/7] core/wfp_ioctl.zig
$B64_5 = ''
Deploy-File -RelativePath "core/wfp_ioctl.zig" -ExpectedLines 438 -Base64Content $B64_5

# [6/7] core/pipe_monitor.zig
$B64_6 = ''
Deploy-File -RelativePath "core/pipe_monitor.zig" -ExpectedLines 181 -Base64Content $B64_6

# [7/7] core/bridge_init.zig
$B64_7 = ''
Deploy-File -RelativePath "core/bridge_init.zig" -ExpectedLines 445 -Base64Content $B64_7


# ============================================================
# Cleanup old backup files from prior phases
# ============================================================
$OldBackups = Get-ChildItem -Path $DeployRoot -Recurse -Filter "*.phase*_backup" -ErrorAction SilentlyContinue
foreach ($Backup in $OldBackups) {
    Remove-Item -Path $Backup.FullName -Force
    Write-Host "  [CLEANUP] Removed: $($Backup.Name)"
}

# ============================================================
# Build verification
# ============================================================
Write-Host ""
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | ForEach-Object { Write-Host $_ }
if ($LASTEXITCODE -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 6 fixes applied"
} else {
    Write-Host "[BUILD] FAILED - check errors above"
    exit 1
}

Write-Host ""
Write-Host "Summary of changes:"
Write-Host "  Phase 6 changes (Low + Info + Bugfix):"
Write-Host "    F6:  nids_analyze: pipe_listener spawn failure now signals shutdown (was orphaning status reporter)"
Write-Host "    F7:  nids_analyze: reload_rules_atomic propagates errors (was silent fail-open)"
Write-Host "    F8:  nids_capture: g_analyze_errors uses .relaxed (was .seq_cst - inconsistent with rest of code)"
Write-Host "    L12: nids_analyze: shutdown summary + ruleset version via std.log (release-visible)"
Write-Host "    L13: windows_capture: WFP BLOCKED alert + stats via std.log (was debug-only)"
Write-Host "    L14: wfp_ioctl: read_events errors + Invalid IP warnings via std.log"
Write-Host "    L15: bridge_init: bridge status summary + printStatus via std.log"
Write-Host "    L16: pipe_monitor: printStats via std.log (was debug-only)"
Write-Host "    L17: minifilter_reader: low-severity events via std.log (was debug-only)"
Write-Host "    M13: nids_analyze: pipe constants (PIPE_ACCESS_DUPLEX, PIPE_WAIT) - named (was magic 3,0)"
Write-Host "    M14: nids_analyze: ERROR_PIPE_CONNECTED via win.Win32Error enum (was magic 535)"
Write-Host "    M15: nids_analyze + IPPROTO_TCP constant (was magic 6)"
Write-Host "    M17: pipe_monitor: MAX_PATH_W, PM_ALERT_BUF, PM_ASCII_MAX, PM_INITIAL_DELAY_S, PM_SCAN_INTERVAL_S"
Write-Host "    M18: bridge_init: DEFCON_DEFAULT constant (was magic 5)"
Write-Host "    S1:  nids_analyze: 8 timestamp @intCast -> @bitCast/@max(0) (panic-safe on clock skew)"
Write-Host "    S2:  nids_analyze: data.len @intCast -> std.math.cast(u32) orelse fallback"
Write-Host "    S3:  wfp_ioctl: out_buf.len @intCast -> std.math.cast(u32) (panic-safe on >4GiB buffer)"
Write-Host "    C3:  minifilter_reader: fixed misleading BP4 doc comment"
Write-Host "    C4:  wfp_ioctl: fixed stale TODO (IOCTL_AEGIS_UNBLOCK_FLOW already defined)"
Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"fix: best practices phase 6 - low/info/bugfix`""
Write-Host "  git push"
